      transition: background-color 250ms ease, color 250ms ease, opacity 250ms ease;
    }

    .waitlist-button:hover,
    .waitlist-button:focus-visible {
      background: #fff;
      color: #000;
      opacity: 1;
    }
  </style>
</head>
