#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

bool valid(int64 k, int64 a, int64 b, int64 c) {
    while (a > 0 || b > 0 || c > 0) {
        if ((a % k + b % k) % k != c % k) return false;
        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int64 a, b, c;
        cin >> a >> b >> c;

        int64 d = a + b - c;
        if (d < 0) {
            cout << 0 << '\n';
        } else if (d == 0) {
            cout << -1 << '\n';
        } else {
            int ans = 0;
            for (int64 i = 1; i * i <= d; ++i) {
                if (d % i != 0) continue;

                int64 j = d / i;
                if (i >= 2 && valid(i, a, b, c)) ++ans;
                if (j != i && j >= 2 && valid(j, a, b, c)) ++ans;
            }
            cout << ans << '\n';
        }
    }
    return 0;
}
```

